import{_ as e,o,c as r,ae as a}from"./chunks/framework.BajMXG5H.js";const m=JSON.parse('{"title":"Real-time Monitoring","description":"","frontmatter":{},"headers":[],"relativePath":"guide/real-time-monitoring.md","filePath":"guide/real-time-monitoring.md"}'),s={name:"guide/real-time-monitoring.md"};function n(d,t,i,l,g,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="real-time-monitoring" tabindex="-1">Real-time Monitoring <a class="header-anchor" href="#real-time-monitoring" aria-label="Permalink to &quot;Real-time Monitoring&quot;">​</a></h1><p>Orchestra monitors all your Claude Code sessions through a single dashboard with live status updates.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When Claude Code runs, it fires hook events at key moments (tool use, completion, errors, subagent activity). Orchestra receives these events via HTTP and updates the dashboard in real-time.</p><h2 id="session-states" tabindex="-1">Session States <a class="header-anchor" href="#session-states" aria-label="Permalink to &quot;Session States&quot;">​</a></h2><p>Each session card shows the current state:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Running</strong></td><td>Claude is actively working</td></tr><tr><td><strong>Waiting Input</strong></td><td>Claude has stopped and is waiting for your input</td></tr><tr><td><strong>Waiting Permission</strong></td><td>Claude needs permission to proceed</td></tr><tr><td><strong>Error</strong></td><td>Something went wrong</td></tr><tr><td><strong>Done</strong></td><td>Session has ended</td></tr></tbody></table><h2 id="activity-types" tabindex="-1">Activity Types <a class="header-anchor" href="#activity-types" aria-label="Permalink to &quot;Activity Types&quot;">​</a></h2><p>The dashboard shows what Claude is currently doing with animated icons:</p><table tabindex="0"><thead><tr><th>Activity</th><th>Description</th><th>Tools</th></tr></thead><tbody><tr><td><strong>Thinking</strong></td><td>LLM inference between tool calls</td><td>—</td></tr><tr><td><strong>Research</strong></td><td>Searching and investigating</td><td>Grep, Glob, WebSearch</td></tr><tr><td><strong>Reading</strong></td><td>Reading files</td><td>Read</td></tr><tr><td><strong>Writing</strong></td><td>Editing or creating files</td><td>Edit, Write</td></tr><tr><td><strong>Coding</strong></td><td>Code editing tools</td><td>Edit, Write (code context)</td></tr><tr><td><strong>Running</strong></td><td>Executing commands</td><td>Bash</td></tr><tr><td><strong>Testing</strong></td><td>Running tests</td><td>Bash (test commands)</td></tr><tr><td><strong>Tooling</strong></td><td>External tool calls</td><td>MCP tools</td></tr><tr><td><strong>Compacting</strong></td><td>Context window compression</td><td>PreCompact event</td></tr><tr><td><strong>Delegating</strong></td><td>Managing subagents</td><td>Active subagents running</td></tr><tr><td><strong>Idle</strong></td><td>No active tool use</td><td>—</td></tr></tbody></table><h2 id="session-cards" tabindex="-1">Session Cards <a class="header-anchor" href="#session-cards" aria-label="Permalink to &quot;Session Cards&quot;">​</a></h2><p>Each session card displays:</p><ul><li><strong>Title</strong> — Derived from the working directory name</li><li><strong>Status badge</strong> — Current session state with color coding</li><li><strong>Activity icon</strong> — Animated icon showing current activity type</li><li><strong>Last activity</strong> — Most recent tool or command output</li><li><strong>Jump button</strong> — One-click navigation to the terminal session</li><li><strong>Subagent count</strong> — Number of active subagents (when delegating)</li></ul><h2 id="team-mode" tabindex="-1">Team Mode <a class="header-anchor" href="#team-mode" aria-label="Permalink to &quot;Team Mode&quot;">​</a></h2><p>When Claude Code runs in <a href="https://docs.anthropic.com/en/docs/claude-code/agent-teams" target="_blank" rel="noreferrer">Agent Teams</a> mode, Orchestra automatically detects team members and displays them with special visual treatment:</p><ul><li><strong>Rainbow border</strong> — Team Lead sessions get a vibrant rainbow-rotating border</li><li><strong>Soft rainbow border</strong> — Team Member sessions get a softer rainbow border</li><li><strong>Role badge</strong> — &quot;Lead&quot; or &quot;Member&quot; badge on each team session card</li><li><strong>Team count</strong> — Status bar shows number of active teams</li></ul><p>Team detection works by monitoring <code>TeammateIdle</code> and <code>TaskCompleted</code> hook events, combined with tmux window grouping.</p><h2 id="supported-hook-events" tabindex="-1">Supported Hook Events <a class="header-anchor" href="#supported-hook-events" aria-label="Permalink to &quot;Supported Hook Events&quot;">​</a></h2><p>Orchestra processes the following Claude Code hook events:</p><table tabindex="0"><thead><tr><th>Event</th><th>Purpose</th></tr></thead><tbody><tr><td>PreToolUse</td><td>Track tool usage start</td></tr><tr><td>PostToolUse</td><td>Track tool completion</td></tr><tr><td>Stop</td><td>Detect session completion</td></tr><tr><td>Notification</td><td>Receive Claude notifications</td></tr><tr><td>SubagentStart</td><td>Track subagent spawning</td></tr><tr><td>SubagentStop</td><td>Track subagent completion</td></tr><tr><td>SessionStart</td><td>Detect session start/resume</td></tr><tr><td>SessionEnd</td><td>Detect session termination</td></tr><tr><td>UserPromptSubmit</td><td>Track user input</td></tr><tr><td>PermissionRequest</td><td>Detect permission prompts</td></tr><tr><td>PreCompact</td><td>Track context compaction</td></tr><tr><td>TeammateIdle</td><td>Team member idle detection</td></tr><tr><td>TaskCompleted</td><td>Team task completion</td></tr></tbody></table>',20)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
